(1833934, 251803, 42638, '<td valign="top">Wow! Absolutely amazing shot!</td>', 'Wow! Absolutely amazing shot!', '2005-11-02 16:31:06.000000', NULL, 1),
(1833937, 251931, 42638, '<td valign="top">Great picture. Love the billowing clouds and the lighting/exposure you used is great. Really matches the title.</td>', 'Great picture. Love the billowing clouds and the lighting/exposure you used is great. Really matches the title.', '2005-11-02 16:31:55.000000', NULL, 1),
(1833938, 251212, 42638, '<td valign="top">Yuck, that is definately a photographers nightmare! Great shot. Love the B&amp;W use</td>', 'Yuck, that is definately a photographers nightmare! Great shot. Love the B&W use', '2005-11-02 16:32:40.000000', NULL, 1),
(1833942, 252154, 42638, '<td valign="top">Wow, I really did have to look for the bike. Nice shot, how did it get there? Love the B&amp;W, really adds to the camilian effect.</td>', 'Wow, I really did have to look for the bike. Nice shot, how did it get there? Love the B&W, really adds to the camilian effect.', '2005-11-02 16:33:25.000000', NULL, 1),
(1833944, 252436, 42638, '<td valign="top">Very nice. Love It. Curious as to how you did it, I''m still new so I have now clue how to even try this. Nice use of space. Great colors.</td>', 'Very nice. Love It. Curious as to how you did it, I''m still new so I have now clue how to even try this. Nice use of space. Great colors.', '2005-11-02 16:35:04.000000', NULL, 1),
(1833947, 250676, 42638, '<td valign="top">Wow, Great picture. Love the lines. I know many frown on the centered subject so to speak but this is great.</td>', 'Wow, Great picture. Love the lines. I know many frown on the centered subject so to speak but this is great.', '2005-11-02 16:36:05.000000', NULL, 1),
(1833950, 251849, 42638, '<td valign="top">Wow, Very busy, Good job. The B&amp;W really brings it out too. Very nice.</td>', 'Wow, Very busy, Good job. The B&W really brings it out too. Very nice.', '2005-11-02 16:36:51.000000', NULL, 1),
(1833952, 251793, 42638, '<td valign="top">Great interpretation. I never thought my kids would ever get out of there!! Great shot! Good use of space. I really like the simple coloring too, really adds to the interpretation.</td>', 'Great interpretation. I never thought my kids would ever get out of there!! Great shot! Good use of space. I really like the simple coloring too, really adds to the interpretation.', '2005-11-02 16:38:12.000000', NULL, 1),
(1833955, 252336, 42638, '<td valign="top">Wow, Wonderful picture. Love all the lines and the coloring is excellent. Great symetry too.</td>', 'Wow, Wonderful picture. Love all the lines and the coloring is excellent. Great symetry too.', '2005-11-02 16:39:29.000000', NULL, 1),
(1833957, 250770, 38549, '<td valign="top">Im sorry but why would you even submit this to the challenge, there is no focus, i can barely see that it is a person, and how do you look busy.........</td>', 'Im sorry but why would you even submit this to the challenge, there is no focus, i can barely see that it is a person, and how do you look busy.........', '2005-11-02 16:40:53.000000', NULL, 1),
(1833966, 252479, 37719, '<td valign="top">I am confused by this shot a bit.  Not sure what your meaning or application to the challenge is.  Beside that the whole image appears fuzzy or out of focus.  If intentional, in my opinion, it detracts from the image.  Also, I am not sure what I should be drawn to - the sock? on the door or the calendar on the wall.  Neither makes much sense to me.</td>', 'I am confused by this shot a bit.  Not sure what your meaning or application to the challenge is.  Beside that the whole image appears fuzzy or out of focus.  If intentional, in my opinion, it detracts from the image.  Also, I am not sure what I should be drawn to - the sock? on the door or the calendar on the wall.  Neither makes much sense to me.', '2005-11-02 16:44:51.000000', NULL, 1),
(1833986, 252277, 45790, '<td valign="top">Good use of wide angle. Sharp.</td>', 'Good use of wide angle. Sharp.', '2005-11-02 16:52:43.000000', NULL, 1),
(1833987, 251859, 42567, '<td valign="top">Great idea...little blur to me...IMO...</td>', 'Great idea...little blur to me...IMO...', '2005-11-02 16:55:24.000000', NULL, 1),
(1833989, 252177, 42567, '<td valign="top">very busy gas station...</td>', 'very busy gas station...', '2005-11-02 16:55:41.000000', NULL, 1),
(1833991, 250787, 42567, '<td valign="top">great lighting..!!  awesome picture...</td>', 'great lighting..!!  awesome picture...', '2005-11-02 16:55:58.000000', NULL, 1),
(1833993, 251883, 42567, '<td valign="top">got''em...good thinking...</td>', 'got''em...good thinking...', '2005-11-02 16:56:29.000000', NULL, 1),
