(1834026, 252371, 45790, '<td valign="top">Interesting subject, but I feel a stretch for the topic.</td>', 'Interesting subject, but I feel a stretch for the topic.', '2005-11-02 17:07:21.000000', NULL, 1),
(1834027, 252050, 45790, '<td valign="top">Needs greater DOF -- too much is out of focus.</td>', 'Needs greater DOF -- too much is out of focus.', '2005-11-02 17:08:09.000000', NULL, 1),
(1834028, 251824, 42567, '<td valign="top">great job..!</td>', 'great job..!', '2005-11-02 17:08:32.000000', NULL, 1),
(1834030, 252131, 45790, '<td valign="top">Yep, under normal metrics this would be downgraded for the "busy" background, but under this topic the distracting background makes the picture!</td>', 'Yep, under normal metrics this would be downgraded for the "busy" background, but under this topic the distracting background makes the picture!', '2005-11-02 17:10:24.000000', NULL, 1),
