(1834033, 251549, 45790, '<td valign="top">It doesn''t look like you took this at the busiest time of day -- perhaps different framing to show more traffic. More pedestrians would be a help as well.</td>', 'It doesn''t look like you took this at the busiest time of day -- perhaps different framing to show more traffic. More pedestrians would be a help as well.', '2005-11-02 17:13:33.000000', NULL, 1),
(1834038, 249819, 45790, '<td valign="top">Good use of long exposure. Sharp image but glare on sign board which I expect could not be avoided.</td>', 'Good use of long exposure. Sharp image but glare on sign board which I expect could not be avoided.', '2005-11-02 17:15:00.000000', NULL, 1),
(1834043, 251883, 39850, '<td valign="top">7 - Like it, good idea, found them.  Criticism; not much, like the composition, angle is good for this shot, maybe some more ''depth'' here or there, a few highlight issues perhaps, but otherwise good ''different'' fit for the Challenge.  I think the frame suits this shot.</td>', '7 - Like it, good idea, found them.  Criticism; not much, like the composition, angle is good for this shot, maybe some more ''depth'' here or there, a few highlight issues perhaps, but otherwise good ''different'' fit for the Challenge.  I think the frame suits this shot.', '2005-11-02 17:16:23.000000', NULL, 1),
(1834046, 251883, 41554, '<td valign="top">Extremely busy... LOL</td>', 'Extremely busy... LOL', '2005-11-02 17:16:54.000000', NULL, 1),
(1834050, 252424, 41554, '<td valign="top">* yawn *</td>', '* yawn *', '2005-11-02 17:17:46.000000', NULL, 1),
