(1834057, 251810, 45790, '<td valign="top">I cringed when I saw this, so it must be good for the challenge. Gotta rate it high.</td>', 'I cringed when I saw this, so it must be good for the challenge. Gotta rate it high.', '2005-11-02 17:20:07.000000', NULL, 1),
(1834060, 252440, 41554, '<td valign="top">A bit out of focus... tiresome to look at. Sorry.</td>', 'A bit out of focus... tiresome to look at. Sorry.', '2005-11-02 17:20:29.000000', NULL, 1),
(1834065, 251048, 45790, '<td valign="top">Fairly busy photographically, but the workers don''t seem busy at all. :-)<br/></td>', 'Fairly busy photographically, but the workers don''t seem busy at all. :-)', '2005-11-02 17:21:23.000000', NULL, 1),
(1834077, 252503, 45191, '<td valign="top">Great light, great perspective, and great focus/DoF!</td>', 'Great light, great perspective, and great focus/DoF!', '2005-11-02 17:24:01.000000', NULL, 1),
(1834080, 251166, 39850, '<td valign="top">7 - Well that''s different.  Undecided on the aspect/rotation.  Like the idea though.  The trucks add to a semi-vertigo type feeling.  Criticism; slightly stronger colors perhaps, not sure.  A different crop, especially to get the road/composition more ''balanced'' may have made this better in my opinion.  Good shot for the Challenge.  Up to 7 from 6.</td>', '7 - Well that''s different.  Undecided on the aspect/rotation.  Like the idea though.  The trucks add to a semi-vertigo type feeling.  Criticism; slightly stronger colors perhaps, not sure.  A different crop, especially to get the road/composition more ''balanced'' may have made this better in my opinion.  Good shot for the Challenge.  Up to 7 from 6.', '2005-11-02 17:24:26.000000', NULL, 1),
(1834091, 250632, 45790, '<td valign="top">Busy on many levels and vibrant. I really like this.</td>', 'Busy on many levels and vibrant. I really like this.', '2005-11-02 17:26:24.000000', NULL, 1),
(1834092, 251849, 42100, '<td valign="top">This one will make you dizzy.  Great photo, like the contrast.</td>', 'This one will make you dizzy.  Great photo, like the contrast.', '2005-11-02 17:26:45.000000', NULL, 1),
(1834096, 249781, 45191, '<td valign="top">Wow!!!! Great photo!!!</td>', 'Wow!!!! Great photo!!!', '2005-11-02 17:27:39.000000', NULL, 1),
