(1834147, 250527, 41554, '<td valign="top">Great light, nice idea...</td>', 'Great light, nice idea...', '2005-11-02 17:48:36.000000', NULL, 1),
(1834153, 251829, 41554, '<td valign="top">Very nice. Shame those darn footprints.</td>', 'Very nice. Shame those darn footprints.', '2005-11-02 17:50:17.000000', NULL, 1),
