(1834212, 252177, 45790, '<td valign="top">WIth that title, you should show the price sign.</td>', 'WIth that title, you should show the price sign.', '2005-11-02 18:17:39.000000', NULL, 1),
(1834217, 252211, 45790, '<td valign="top">The angle here is wrong to see the bee. Compare yours with the four or five other "busy bee" entries in this challenge.</td>', 'The angle here is wrong to see the bee. Compare yours with the four or five other "busy bee" entries in this challenge.', '2005-11-02 18:21:26.000000', NULL, 1),
(1834222, 252326, 45790, '<td valign="top">Flower is OK, but has some blown highlights. Kudos for capturing bee in flight, but you should have told her to turn around and face the camera.</td>', 'Flower is OK, but has some blown highlights. Kudos for capturing bee in flight, but you should have told her to turn around and face the camera.', '2005-11-02 18:24:12.000000', NULL, 1),
(1834224, 252336, 42100, '<td valign="top">Great exposure and contrast, very well done!</td>', 'Great exposure and contrast, very well done!', '2005-11-02 18:24:49.000000', NULL, 1),
(1834229, 252423, 45790, '<td valign="top">Ironically, one of the best "Busy as a Bee" pictures. Not only is the bee busy (well, would be if she were alive) but the picture is photographically busy as well.</td>', 'Ironically, one of the best "Busy as a Bee" pictures. Not only is the bee busy (well, would be if she were alive) but the picture is photographically busy as well.', '2005-11-02 18:25:48.000000', NULL, 1),
(1834328, 251629, 39850, '<td valign="top">7 - Good effort, good shot for the Challenge.  Criticism; camera/lens dependent, more focus.  Different crop may have also made this better in my opinion.  Good idea.</td>', '7 - Good effort, good shot for the Challenge.  Criticism; camera/lens dependent, more focus.  Different crop may have also made this better in my opinion.  Good idea.', '2005-11-02 19:02:32.000000', NULL, 1),
(1834382, 251380, 35804, '<td valign="top">...then why is it in the "Busy" challenge?</td>', '...then why is it in the "Busy" challenge?', '2005-11-02 19:24:38.000000', NULL, 1),
(1834391, 251829, 35804, '<td valign="top">Such beautiful patterns, rhythm and light...nicely done.</td>', 'Such beautiful patterns, rhythm and light...nicely done.', '2005-11-02 19:27:07.000000', NULL, 1),
(1834405, 249741, 35804, '<td valign="top">Love the colors....reminds me of an old polaroid.</td>', 'Love the colors....reminds me of an old polaroid.', '2005-11-02 19:30:37.000000', NULL, 1),
(1834411, 249864, 35804, '<td valign="top">ahhhhhhh...boxelder beetles...I used to have a ton ofthem around my previous house...they sure like that sunshine don''t they?</td>', 'ahhhhhhh...boxelder beetles...I used to have a ton ofthem around my previous house...they sure like that sunshine don''t they?', '2005-11-02 19:32:40.000000', NULL, 1),
(1834462, 251449, 39850, '<td valign="top">7 - Good shot and idea for the Challenge - sometimes the titles do matter, without being ''forced'', well done.  Criticism; not much, the ''odd angle'' adds to the shot, so maybe more of an exaggeration, not sure.  The ''everyday feel'' with the people in the background adds too.  Maybe a different crop, eliminating the sleeve, incorporating more of the ''handset'', may have made this better in my opinion.</td>', '7 - Good shot and idea for the Challenge - sometimes the titles do matter, without being ''forced'', well done.  Criticism; not much, the ''odd angle'' adds to the shot, so maybe more of an exaggeration, not sure.  The ''everyday feel'' with the people in the background adds too.  Maybe a different crop, eliminating the sleeve, incorporating more of the ''handset'', may have made this better in my opinion.', '2005-11-02 19:46:05.000000', NULL, 1),
(1834471, 251391, 45790, '<td valign="top">The lighting is striking. Great color. But how is this "busy"?</td>', 'The lighting is striking. Great color. But how is this "busy"?', '2005-11-02 19:48:07.000000', NULL, 1),
(1834483, 251495, 46468, '<td valign="top">Simple but conveys the message well, good focus, nice contrast with the red against the black and white</td>', 'Simple but conveys the message well, good focus, nice contrast with the red against the black and white', '2005-11-02 19:52:19.000000', NULL, 1),
(1834490, 252494, 46468, '<td valign="top">he is definately busy, cell phone on his side adds to it, like it</td>', 'he is definately busy, cell phone on his side adds to it, like it', '2005-11-02 19:54:28.000000', NULL, 1),
(1834505, 252436, 46468, '<td valign="top">very well done, all three seem to be "busy" doing their job, and not paying any attention to you or anything else</td>', 'very well done, all three seem to be "busy" doing their job, and not paying any attention to you or anything else', '2005-11-02 19:58:23.000000', NULL, 1),
(1834507, 252503, 46468, '<td valign="top">nice macro capture, love that the spider is actually "busy" working on the web, and the dew drops add to the busy pattern, well done</td>', 'nice macro capture, love that the spider is actually "busy" working on the web, and the dew drops add to the busy pattern, well done', '2005-11-02 19:58:45.000000', NULL, 1),
(1834513, 251137, 44503, '<td valign="top">Beautiful shot. Excellent image, relection, and timing for the fog.</td>', 'Beautiful shot. Excellent image, relection, and timing for the fog.', '2005-11-02 20:02:03.000000', NULL, 1),
(1834516, 252336, 46468, '<td valign="top">beautiful "busy" architecture, nice capture</td>', 'beautiful "busy" architecture, nice capture', '2005-11-02 20:02:44.000000', NULL, 1),
