(1834529, 251952, 46468, '<td valign="top">Definately one "busy" man, would have scored higher if the pic would have been bigger, harder to see details if not close to max allowed size</td>', 'Definately one "busy" man, would have scored higher if the pic would have been bigger, harder to see details if not close to max allowed size', '2005-11-02 20:07:05.000000', NULL, 1),
