(1838229, 252023, 45931, '<td valign="top">I know how it feels</td>', 'I know how it feels', '2005-11-04 14:37:47.000000', NULL, 1),
(1838230, 252495, 45926, '<td valign="top">whoa, very cool. did u cut them all l out by yourself?! dude..  haha, i love this picture. nice contrasting colors, and designs!</td>', 'whoa, very cool. did u cut them all l out by yourself?! dude..  haha, i love this picture. nice contrasting colors, and designs!', '2005-11-04 14:38:39.000000', NULL, 1),
(1838234, 252273, 45926, '<td valign="top">wow, very pretty. i took a picture of a bee too, but i like yours much better. i love how hazy it looks on the plant on the right side of the picture. very, very cool. awesome job!</td>', 'wow, very pretty. i took a picture of a bee too, but i like yours much better. i love how hazy it looks on the plant on the right side of the picture. very, very cool. awesome job!', '2005-11-04 14:40:28.000000', NULL, 1),
(1838237, 250715, 739, '<td valign="top">the highlights are a bit too strong.  I love the pink that''s sprinkled all around.</td>', 'the highlights are a bit too strong.  I love the pink that''s sprinkled all around.', '2005-11-04 14:44:30.000000', NULL, 1),
(1838242, 251360, 45926, '<td valign="top">whoa. awesome picture. sorry to compare your photograph to a movie scene, but this really reminds me of a section in the movie, "X-Men." haha. i''m such a dork. i seriously love this picture. the cloudy sky in the background is so awesome/beautiful. the way that the focus isn''t on the model really works. i applaud ya. great job.</td>', 'whoa. awesome picture. sorry to compare your photograph to a movie scene, but this really reminds me of a section in the movie, "X-Men." haha. i''m such a dork. i seriously love this picture. the cloudy sky in the background is so awesome/beautiful. the way that the focus isn''t on the model really works. i applaud ya. great job.', '2005-11-04 14:47:06.000000', NULL, 1),
(1838250, 250046, 45926, '<td valign="top">wow, awesome picture. u captured thei movement beautifully. i don''t really like the color choice in the border though. i think that maybe a different color would''ve made this picture look even better. great job.</td>', 'wow, awesome picture. u captured thei movement beautifully. i don''t really like the color choice in the border though. i think that maybe a different color would''ve made this picture look even better. great job.', '2005-11-04 14:49:42.000000', NULL, 1),
(1838254, 251345, 45926, '<td valign="top">yay candy corn!! makes me feel fat and happy. ^_^</td>', 'yay candy corn!! makes me feel fat and happy. ^_^', '2005-11-04 14:50:51.000000', NULL, 1),
(1838262, 252276, 45926, '<td valign="top">my friend rachel says that she doesn''t like the title. but that''s the thing that gives it humor. haha. ..see? eh? eh?!! lol. u captured the movement really well. the black and white (or sepia?) effect really works. awesome job. keep those balls busy.</td>', 'my friend rachel says that she doesn''t like the title. but that''s the thing that gives it humor. haha. ..see? eh? eh?!! lol. u captured the movement really well. the black and white (or sepia?) effect really works. awesome job. keep those balls busy.', '2005-11-04 14:52:55.000000', NULL, 1),
