(1839031, 251849, 32997, '<td valign="top">nice work..love the angle and tones..</td>', 'nice work..love the angle and tones..', '2005-11-04 20:01:33.000000', NULL, 1),
(1839102, 250046, 44172, '<td valign="top">oh - nice capture - they certainly look busy and despite all the action it''s all really clear - good job!</td>', 'oh - nice capture - they certainly look busy and despite all the action it''s all really clear - good job!', '2005-11-04 20:47:51.000000', NULL, 1),
(1839150, 250438, 31859, '<td valign="top">pretty picture, would be nicer w/o time stamp.</td>', 'pretty picture, would be nicer w/o time stamp.', '2005-11-04 21:09:52.000000', NULL, 1),
(1839193, 251931, 32754, '<td valign="top">great shot and compositon..the clouds of steam and smoke are fantastic; I love this whole image: it has movement and power.</td>', 'great shot and compositon..the clouds of steam and smoke are fantastic; I love this whole image: it has movement and power.', '2005-11-04 21:36:27.000000', NULL, 1),
(1839380, 250409, 42574, '<td valign="top">I love the colors in this shot.</td>', 'I love the colors in this shot.', '2005-11-04 22:47:43.000000', NULL, 1),
(1839385, 252020, 41574, '<td valign="top">It actually looks rather empty and quiet.</td>', 'It actually looks rather empty and quiet.', '2005-11-04 22:50:11.000000', NULL, 1),
(1839386, 252354, 41574, '<td valign="top">It''s like a lunch-break; this hardly says "busy" to me.</td>', 'It''s like a lunch-break; this hardly says "busy" to me.', '2005-11-04 22:50:46.000000', NULL, 1),
(1839387, 252425, 31403, '<td valign="top">this is a cool effect, but what is the subject of the photo?  the little basket of napkins?  If this effect was applied to a strong subject you''d have a terrific photo - but as it is it doesn''t do much for me - did I mention I love the effect?</td>', 'this is a cool effect, but what is the subject of the photo?  the little basket of napkins?  If this effect was applied to a strong subject you''d have a terrific photo - but as it is it doesn''t do much for me - did I mention I love the effect?', '2005-11-04 22:51:02.000000', NULL, 1),
(1839389, 252348, 42574, '<td valign="top">I like it, but I think it would have been nice if the whole leaf could have been in focus.</td>', 'I like it, but I think it would have been nice if the whole leaf could have been in focus.', '2005-11-04 22:51:25.000000', NULL, 1),
(1839399, 251816, 31403, '<td valign="top">more contrast would make this stronger IMO</td>', 'more contrast would make this stronger IMO', '2005-11-04 22:57:07.000000', NULL, 1),
(1839411, 252292, 31403, '<td valign="top">with the head cropped so tight, the black under the chin feels ackward.  I would like to see this with the bottom cropped right against the chin to see if it feels more balanced.  Love the emotion, and the lighting is cool too - great texture in the skin 7</td>', 'with the head cropped so tight, the black under the chin feels ackward.  I would like to see this with the bottom cropped right against the chin to see if it feels more balanced.  Love the emotion, and the lighting is cool too - great texture in the skin 7', '2005-11-04 23:00:08.000000', NULL, 1),
(1839427, 252226, 44172, '<td valign="top">great "busy" composition - clarity - and colors - so many cool things to look at - you did a great job :)</td>', 'great "busy" composition - clarity - and colors - so many cool things to look at - you did a great job :)', '2005-11-04 23:07:00.000000', NULL, 1),
(1839429, 251400, 44172, '<td valign="top">so sweet, great capture and title, good image and idea for this challenge - hope it does well - but a great image to cherish no matter the votes :)</td>', 'so sweet, great capture and title, good image and idea for this challenge - hope it does well - but a great image to cherish no matter the votes :)', '2005-11-04 23:09:13.000000', NULL, 1),
