(1839563, 250224, 43442, '<td valign="top">Cropping out the left side would help ones eyes follow the Traffic, making this a better photograph.</td>', 'Cropping out the left side would help ones eyes follow the Traffic, making this a better photograph.', '2005-11-05 00:12:44.000000', NULL, 1),
(1839570, 252216, 28471, '<td valign="top">While this photo does have busy colors it appears you used an on camera frontal flash that  flattened the image.  The black hair contains no details while the white shirt in some places have appeared to have lost some hightlights.</td>', 'While this photo does have busy colors it appears you used an on camera frontal flash that  flattened the image.  The black hair contains no details while the white shirt in some places have appeared to have lost some hightlights.', '2005-11-05 00:14:49.000000', NULL, 1),
