INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1839583, 252471, 28471, '<td valign="top">Good concept, if not common.  Good execution.  I like your choice of shutter speed as it helps make the image seem more busy.</td>', 'Good concept, if not common.  Good execution.  I like your choice of shutter speed as it helps make the image seem more busy.', '2005-11-05 00:18:26.000000', NULL, 1),
(1839587, 250510, 28471, '<td valign="top">Great shot.  Truly looks busy but also very structured at the same time.  This is important in this challenge as it is tempting at first to break the rules and create a busy photo period.  just because a photo is busy does not mean it is good.  All that said you have done an excellent job here. (9).</td>', 'Great shot.  Truly looks busy but also very structured at the same time.  This is important in this challenge as it is tempting at first to break the rules and create a busy photo period.  just because a photo is busy does not mean it is good.  All that said you have done an excellent job here. (9).', '2005-11-05 00:21:02.000000', NULL, 1),
(1839589, 250438, 43442, '<td valign="top">Great shot too bad the Date &amp; time is on the bottom of photo.   Cropping the bottonm of this photo would have eliminated the date and Time and helped the photo. Great exposure on the backgound.   I hope you also tried another shot with an longer exposure to have the water flow instead of stopping the water.    I still have to give this a  perfect score of 10.</td>', 'Great shot too bad the Date & time is on the bottom of photo.   Cropping the bottonm of this photo would have eliminated the date and Time and helped the photo. Great exposure on the backgound.   I hope you also tried another shot with an longer exposure to have the water flow instead of stopping the water.    I still have to give this a  perfect score of 10.', '2005-11-05 00:21:30.000000', NULL, 1),
(1839591, 252406, 28471, '<td valign="top">This image has been over satured in PS.</td>', 'This image has been over satured in PS.', '2005-11-05 00:21:45.000000', NULL, 1),
(1839594, 251159, 28471, '<td valign="top">This photo is looks good compostion but the lighting is flat.  I think this photo would have benefited from a fill flash at least.</td>', 'This photo is looks good compostion but the lighting is flat.  I think this photo would have benefited from a fill flash at least.', '2005-11-05 00:23:15.000000', NULL, 1),
(1839596, 251391, 43442, '<td valign="top">Great shot , even better shot taking away some space from the Right side and adding alittle more on the left side.  Still a High scoring Photograph.</td>', 'Great shot , even better shot taking away some space from the Right side and adding alittle more on the left side.  Still a High scoring Photograph.', '2005-11-05 00:24:29.000000', NULL, 1),
(1839599, 252157, 28471, '<td valign="top">Great shot.  Definately meets the challenge.  Did you intentionally shoot this photo slightly crooked?</td>', 'Great shot.  Definately meets the challenge.  Did you intentionally shoot this photo slightly crooked?', '2005-11-05 00:25:06.000000', NULL, 1),
(1839602, 252152, 28471, '<td valign="top">This is a great idea but I feel it suffered due to it being out of focus or cropped from a much larger image.</td>', 'This is a great idea but I feel it suffered due to it being out of focus or cropped from a much larger image.', '2005-11-05 00:27:15.000000', NULL, 1),
(1839604, 251931, 43442, '<td valign="top">Wow ,  This would be an interesting experament to  try using Inferred film.</td>', 'Wow ,  This would be an interesting experament to  try using Inferred film.', '2005-11-05 00:28:13.000000', NULL, 1),
(1839606, 252063, 28471, '<td valign="top">This bird is direct center of the frame which is generally a bad idea photographically as the eye tends to ignore the middle of the photo.  Also it does not seem to meet the challenge as it does not seem busy in any way.</td>', 'This bird is direct center of the frame which is generally a bad idea photographically as the eye tends to ignore the middle of the photo.  Also it does not seem to meet the challenge as it does not seem busy in any way.', '2005-11-05 00:28:37.000000', NULL, 1),
(1839608, 252154, 43442, '<td valign="top">Wow  Wow Wow............</td>', 'Wow  Wow Wow............', '2005-11-05 00:29:30.000000', NULL, 1),
(1839617, 251931, 28471, '<td valign="top">Excellent shot but then again I am really drawn to industrial imagery.  The detail in this photo is superb. (10)</td>', 'Excellent shot but then again I am really drawn to industrial imagery.  The detail in this photo is superb. (10)', '2005-11-05 00:33:55.000000', NULL, 1),
(1839618, 249831, 43442, '<td valign="top">Interesting subject.    Cropping some of the right side of photo would help one keep focused on the Pumpkin.   ( the lighter grey draws one eyes away from the pumpkin )</td>', 'Interesting subject.    Cropping some of the right side of photo would help one keep focused on the Pumpkin.   ( the lighter grey draws one eyes away from the pumpkin )', '2005-11-05 00:33:57.000000', NULL, 1),
