(1839622, 249781, 43442, '<td valign="top">In close or a very long lens...............buzzzzzzzzzzzzzzzzzzzzz</td>', 'In close or a very long lens...............buzzzzzzzzzzzzzzzzzzzzz', '2005-11-05 00:34:55.000000', NULL, 1),
