(1839873, 251942, 42792, '<td valign="top">Poignant in the desperation conveyed.  Love it.  Doesn''t belong in this challenge tho''.  I understand what you''re getting at but without the title, it wouldn''t have crossed my mind at all.<br/> <br/>2nd look and bumping it up anyway - 8.</td>', 'Poignant in the desperation conveyed.  Love it.  Doesn''t belong in this challenge tho''.  I understand what you''re getting at but without the title, it wouldn''t have crossed my mind at all. 2nd look and bumping it up anyway - 8.', '2005-11-05 05:40:02.000000', NULL, 1),
(1839878, 250046, 42792, '<td valign="top">Great action shot.  A little small to really appreciate its impact but guess not your fault.  My only gripe - the blue border spoils it.</td>', 'Great action shot.  A little small to really appreciate its impact but guess not your fault.  My only gripe - the blue border spoils it.', '2005-11-05 05:42:22.000000', NULL, 1),
