(1846358, 252326, 24981, '<td valign="top">Love the colors, just having a hard time seeing where the focus is.</td>', 'Love the colors, just having a hard time seeing where the focus is.', '2005-11-07 23:36:45.000000', NULL, 1),
(1846372, 250676, 24981, '<td valign="top">It''s nice to see construction as opposed to destruction. Your photo fits the challenge well. Good Luck!</td>', 'It''s nice to see construction as opposed to destruction. Your photo fits the challenge well. Good Luck!', '2005-11-07 23:39:15.000000', NULL, 1),
(1846494, 251701, 36371, '<td valign="top">Don''t see ''''Busy'''' here...sorry.</td>', 'Don''t see ''''Busy'''' here...sorry.', '2005-11-08 00:22:06.000000', NULL, 1),
(1846498, 250438, 36371, '<td valign="top">NOOO!! The dreaded date stamp!!!!</td>', 'NOOO!! The dreaded date stamp!!!!', '2005-11-08 00:25:07.000000', NULL, 1),
(1846501, 252221, 36371, '<td valign="top">Very nice composition with what looks like ''''Momma'''' on the right side...<br/>VERY YUCK in a spidery sorta way!! I rate it a 9.</td>', 'Very nice composition with what looks like ''''Momma'''' on the right side...VERY YUCK in a spidery sorta way!! I rate it a 9.', '2005-11-08 00:26:52.000000', NULL, 1),
(1846568, 250059, 25355, '<td valign="top">A very centred subject, but it works because of the alignment of many of the sticks and pieces of wood that seem to be pointing at the bug.</td>', 'A very centred subject, but it works because of the alignment of many of the sticks and pieces of wood that seem to be pointing at the bug.', '2005-11-08 01:23:58.000000', NULL, 1),
(1846574, 249831, 25355, '<td valign="top">the strange object in the back is really distracting. What is it?????</td>', 'the strange object in the back is really distracting. What is it?????', '2005-11-08 01:27:39.000000', NULL, 1),
(1846577, 251931, 25355, '<td valign="top">That''s quite frightening.</td>', 'That''s quite frightening.', '2005-11-08 01:28:36.000000', NULL, 1),
(1846691, 251837, 46679, '<td valign="top">This is an interresting way to present a often shown theme. I like the way you can almost see individual cars in the foreground. The photo is a tad to exposed for my taste but that should be easy to rectify.</td>', 'This is an interresting way to present a often shown theme. I like the way you can almost see individual cars in the foreground. The photo is a tad to exposed for my taste but that should be easy to rectify.', '2005-11-08 03:12:25.000000', NULL, 1),
(1846696, 251495, 46679, '<td valign="top">Aww, good idea but the props are less than interresting. The phone is cheap and the bra is not very romantic. Two white spots on it disturbing. Finally the background is sterile. My suggestion: Find an old, romantic phone, finde a lacy bra and put the thing on a bed. Last but not least: use daylight from one source through curtains.</td>', 'Aww, good idea but the props are less than interresting. The phone is cheap and the bra is not very romantic. Two white spots on it disturbing. Finally the background is sterile. My suggestion: Find an old, romantic phone, finde a lacy bra and put the thing on a bed. Last but not least: use daylight from one source through curtains.', '2005-11-08 03:16:41.000000', NULL, 1),
(1846699, 252444, 46679, '<td valign="top">I''m not sure about this one ... maybe because she''s looking into the camera. Good idea though.</td>', 'I''m not sure about this one ... maybe because she''s looking into the camera. Good idea though.', '2005-11-08 03:19:46.000000', NULL, 1),
(1846700, 252503, 46679, '<td valign="top">Very well done. Pinsharp where it should be and the light on the underside is just dazzling. But the photo is too frozen for my taste to convey the sense of "busy".</td>', 'Very well done. Pinsharp where it should be and the light on the underside is just dazzling. But the photo is too frozen for my taste to convey the sense of "busy".', '2005-11-08 03:21:30.000000', NULL, 1),
