(1848026, 251829, 3102, '<td valign="top">Very cool shot!  I like the use of B&amp;W here (something that isn''t appealing to me all that often).  Great job with the depth of field, too.</td>', 'Very cool shot!  I like the use of B&W here (something that isn''t appealing to me all that often).  Great job with the depth of field, too.', '2005-11-08 18:26:44.000000', NULL, 1),
(1848032, 251931, 3102, '<td valign="top">This has such a 50''s kind of feel to it... like old photos of Pittsburgh back when steel was king around here.  I like the "dank" feeling of it... nice work!</td>', 'This has such a 50''s kind of feel to it... like old photos of Pittsburgh back when steel was king around here.  I like the "dank" feeling of it... nice work!', '2005-11-08 18:28:41.000000', NULL, 1),
(1848036, 252503, 3102, '<td valign="top">Very nicely done -- I''m always jealous of people who are able to pull off such good macros!</td>', 'Very nicely done -- I''m always jealous of people who are able to pull off such good macros!', '2005-11-08 18:29:54.000000', NULL, 1),
(1848041, 252386, 42198, '<td valign="top">A bit noisy.</td>', 'A bit noisy.', '2005-11-08 18:32:28.000000', NULL, 1),
(1848044, 251942, 3102, '<td valign="top">Has a great "National Geographic" feel to it, and it certainly meets the challenge as far as the lady is concerned!  Great job with the toning... the colors are great!</td>', 'Has a great "National Geographic" feel to it, and it certainly meets the challenge as far as the lady is concerned!  Great job with the toning... the colors are great!', '2005-11-08 18:33:53.000000', NULL, 1),
(1848049, 249819, 3102, '<td valign="top">Excellent job with the long exposure to really capture the busy feel of the place!  My only slight complaint would be with it is the sign (or whatever it is) dangling down on the right... otherwise, super shot!</td>', 'Excellent job with the long exposure to really capture the busy feel of the place!  My only slight complaint would be with it is the sign (or whatever it is) dangling down on the right... otherwise, super shot!', '2005-11-08 18:35:38.000000', NULL, 1),
