(1848171, 252056, 46468, '<td valign="top">Good capture, nicely done, focus is great, in fact I can clearly see the veins in the hands, which as I nurse I always look for. Well done</td>', 'Good capture, nicely done, focus is great, in fact I can clearly see the veins in the hands, which as I nurse I always look for. Well done', '2005-11-08 19:16:25.000000', NULL, 1),
(1848195, 250825, 42968, '<td valign="top">Love the colors....clarity in the wings, close flowers, and background is nice as it adds to the pic, however it is not distracting...</td>', 'Love the colors....clarity in the wings, close flowers, and background is nice as it adds to the pic, however it is not distracting...', '2005-11-08 19:29:31.000000', NULL, 1),
