(1848288, 252406, 24981, '<td valign="top">I think this fits the challenge well, but the colors are just a bit too over-saturated. Had they not been, I would have easily givin this an 8. - 5</td>', 'I think this fits the challenge well, but the colors are just a bit too over-saturated. Had they not been, I would have easily givin this an 8. - 5', '2005-11-08 20:03:01.000000', NULL, 1),
