(1848307, 250984, 24981, '<td valign="top">Very busy with lots of distacting elements, so it meets the challenge well. If it were at all possible to crop so that your main focus isn''t in the center and possibly a bit larger so we could see more detail on the little guy/gal. Congrats on finding this little critter. :) 6</td>', 'Very busy with lots of distacting elements, so it meets the challenge well. If it were at all possible to crop so that your main focus isn''t in the center and possibly a bit larger so we could see more detail on the little guy/gal. Congrats on finding this little critter. :) 6', '2005-11-08 20:12:35.000000', NULL, 1),
(1848318, 252417, 45802, '<td valign="top">I think this nice idea would work even better if the records weren''t in rows.</td>', 'I think this nice idea would work even better if the records weren''t in rows.', '2005-11-08 20:19:04.000000', NULL, 1),
(1848319, 251793, 37961, '<td valign="top">Adorable. I hope it wins. 10.</td>', 'Adorable. I hope it wins. 10.', '2005-11-08 20:20:27.000000', NULL, 1),
