(1852265, 252336, 4285, '<td valign="top">WOW Karen.  Congrats on your blue ribbon.  Now that didn''t take you long did it? Nice shot.</td>', 'WOW Karen.  Congrats on your blue ribbon.  Now that didn''t take you long did it? Nice shot.', '2005-11-09 18:16:39.000000', NULL, 0),
(1852279, 251803, 45587, '<td valign="top">simply stunning. Congrats!</td>', 'simply stunning. Congrats!', '2005-11-09 18:20:37.000000', NULL, 0),
(1852445, 252336, 22734, '<td valign="top">This image reaches out to pull the viewer in. It is a very good capture because the exposure was well addressed to give it its beauty. You look at a modern structure and the mind absorbs all elements pretty quickly, however, this image is a feasr for the eyes as the more you find the more there is. Congratulations on your well earned BLUE.</td>', 'This image reaches out to pull the viewer in. It is a very good capture because the exposure was well addressed to give it its beauty. You look at a modern structure and the mind absorbs all elements pretty quickly, however, this image is a feasr for the eyes as the more you find the more there is. Congratulations on your well earned BLUE.', '2005-11-09 19:18:26.000000', NULL, 0),
(1852452, 251803, 22734, '<td valign="top">This is like one of the those once in a lifetime image. The figure dangling and the fury of the clous swirls adds even more interest. Congratulations on your RED.</td>', 'This is like one of the those once in a lifetime image. The figure dangling and the fury of the clous swirls adds even more interest. Congratulations on your RED.', '2005-11-09 19:20:35.000000', NULL, 0),
(1852455, 251931, 22734, '<td valign="top">I love this image because of the subtle touch of color amidst all the steam. It is indeed a monumental capture. Congratulations on your Yellow.</td>', 'I love this image because of the subtle touch of color amidst all the steam. It is indeed a monumental capture. Congratulations on your Yellow.', '2005-11-09 19:22:30.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1852489, 252336, 14773, '<td valign="top">And a newfie at that!!! I''m some proud! ;-)</td>', 'And a newfie at that!!! I''m some proud! ;-)', '2005-11-09 19:32:08.000000', NULL, 0),
(1852549, 251942, 31813, '<td valign="top">Manny, <br/> <br/>Great composition.  <br/> <br/>I love the triangles--classic!  Mother''s head to each child''s head and the the two found in the mother''s clothing - red triangle and multi-coloured triangle.  There are others but those are the most dominant.<br/> <br/> I also love their eyes.  All three looking outward and up but in a different directions while the person in white (background) is looking inward and down.<br/> <br/>A great top 10.</td>', 'Manny,  Great composition.   I love the triangles--classic!  Mother''s head to each child''s head and the the two found in the mother''s clothing - red triangle and multi-coloured triangle.  There are others but those are the most dominant.  I also love their eyes.  All three looking outward and up but in a different directions while the person in white (background) is looking inward and down. A great top 10.', '2005-11-09 19:51:28.000000', NULL, 0),
(1852611, 251883, 37719, '<td valign="top">I commented during the challenge, but revisited it still captures my attention.  This is such a great photo and a very creative idea.  I love the colors - very crisp.  The focus is spot on and the lighting very well done.  Great job on this!<br/> <br/>(got a 10 from me by the way)</td>', 'I commented during the challenge, but revisited it still captures my attention.  This is such a great photo and a very creative idea.  I love the colors - very crisp.  The focus is spot on and the lighting very well done.  Great job on this! (got a 10 from me by the way)', '2005-11-09 20:09:11.000000', NULL, 0),
(1852654, 251803, 15266, '<td valign="top">Love Love Love this image.  Really well seen, well done. Congrats.</td>', 'Love Love Love this image.  Really well seen, well done. Congrats.', '2005-11-09 20:18:12.000000', NULL, 0),
(1852708, 252221, 37719, '<td valign="top">Perhaps a little blurry, but this is a great capture.  You really ahd to be ther at the right time to get this.  Nice job.  Another shot I would love to see a tighter crop before resizeng - bring those little buggers right up and in your face.  Again,great capture!</td>', 'Perhaps a little blurry, but this is a great capture.  You really ahd to be ther at the right time to get this.  Nice job.  Another shot I would love to see a tighter crop before resizeng - bring those little buggers right up and in your face.  Again,great capture!', '2005-11-09 20:30:38.000000', NULL, 0),
(1852982, 252221, 39850, '<td valign="top">99% sure this is Peucetia Viridans ''Green Lynx Spider''.<br/> <br/><i>Arthropods/Arthropoda/Arachnids/Arachnida/Spiders(Araneae)/Lynx Spiders(Oxyopidae)/Peucetia/Green Lynx Spider(Peucetia viridans)</i>. <br/> <br/>Information found at <a href="//bugguide.net" rel="nofollow" target="_blank">BugGuide.Net</a>.  <a href="//bugguide.net/node/view/11171" rel="nofollow" target="_blank">Here</a> is another picture of ''Momma''.  <a href="//bugguide.net/node/view/34476" rel="nofollow" target="_blank">  Here </a> and <a href="//bugguide.net/node/view/34478" rel="nofollow" target="_blank">here</a> are two more pictures of the spiderlings.<br/> <br/>After looking at these shots on BugGuide.Net, it seems you may have had more potential to capture the seemingly vivid green of this spider.  As for the shot of the spiderlings, I think a different crop may have made it a better shot, if possible.</td>', '99% sure this is Peucetia Viridans ''Green Lynx Spider''. Arthropods/Arthropoda/Arachnids/Arachnida/Spiders(Araneae)/Lynx Spiders(Oxyopidae)/Peucetia/Green Lynx Spider(Peucetia viridans).  Information found at BugGuide.Net.  Here is another picture of ''Momma''.    Here  and here are two more pictures of the spiderlings. After looking at these shots on BugGuide.Net, it seems you may have had more potential to capture the seemingly vivid green of this spider.  As for the shot of the spiderlings, I think a different crop may have made it a better shot, if possible.', '2005-11-09 22:04:36.000000', NULL, 0),
(1852986, 252336, 14458, '<td valign="top">Absolutely Wow!<br/> <br/>I''ve gotten some shots in churchs with no tripod by laying the camera on the floor, small aperture, wide lens, self-timer; and then aggressively cropping to get a good composition.  But this one - total wow.  Congratulations.</td>', 'Absolutely Wow! I''ve gotten some shots in churchs with no tripod by laying the camera on the floor, small aperture, wide lens, self-timer; and then aggressively cropping to get a good composition.  But this one - total wow.  Congratulations.', '2005-11-09 22:05:05.000000', NULL, 0),
